use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── C: the gate weights are an INTERMEDIATE the consumer can
        // recompute — fold the SCALE→SIGMOID→SCALE chain into the consumer
        // as a template arm reading the RAW weights, and four kernels
        // become one. ──
        KernelRule {
            rule_id: "sigmoid-gate-chain-folded-into-consumer-template-arm".to_string(),
            gpu_concept: "MECHANISM (sigmoid gate chain folded into consumer template arm; category C — fusion): the graph builds hc_post gate weights via a chain of separate elementwise ops — hc_combine computes `w = 2*sigmoid(inject/hc)`, a SCALE→SIGMOID→SCALE chain over the RAW `inject` weights — and the fusion makes the CONSUMER kernel compute the gated weight from the raw weights instead of materializing the chain's output tensor. Commit message (verbatim): 'hc_combine builds the hc_post weights as 2*sigmoid(inject/hc); dsv4_hc_post_f32 now takes a gated template flag and computes scale_out*sigmoid(scale_in*p) from the raw weights, so the chain runs as one kernel instead of four.' The consumer kernel gains a `template <bool has_comb, bool gated>` arm whose body (verbatim, dsv4-hc.cu:185-190): 'float p = post[idst*sp0 + it*sp1];' / 'if constexpr (gated) {' / '    p = gate_scale_out * (1.0f / (1.0f + expf(-(gate_scale_in * p))));' / '}' — the scalars the eager chain applied as two SCALE factors now ride the fused expression. The HOST rewires the SOURCE tensor, not the data (verbatim, dsv4-hc.cu:290-292): 'const bool          gated = gate_scale_in != nullptr;' and 'const ggml_tensor * post  = gated ? gate_scale_in->src[0] : dst->src[2];' — when fused, the consumer reads the RAW pre-chain weights through the gate node's src[0], and the two gate scalars are launch-known op params ('const float gate_in  = gated ? ggml_get_op_params_f32(gate_scale_in,  0) : 1.0f;' — dsv4-hc.cu:293-294), never tensor loads. ADMISSION is a graph-pattern match (ggml-cuda.cu:3550-3570, verbatim): 'std::initializer_list<enum ggml_op> hc_post_gate_ops = { GGML_OP_SCALE, GGML_OP_UNARY, GGML_OP_SCALE, GGML_OP_DSV4_HC_POST };' + 'ggml_check_edges(cgraph, node_idx, {{1, 0, 0}, {2, 0, 1}, {3, 2, 2}})' pinning the chain wiring (sigmoid reads scale_in, scale_out reads sigmoid, hc_post reads scale_out at src[2]), the unary must BE sigmoid ('ggml_get_unary_op(sigmoid) == GGML_UNARY_OP_SIGMOID'), and the BIAS GUARD — 'a bias on either scale is not handled' enforced as 'ggml_get_op_params_f32(scale_in, 1) == 0.0f && ggml_get_op_params_f32(scale_out, 1) == 0.0f' — plus the same-shape guard ('ggml_are_same_shape(scale_in->src[0], scale_out)'). Dispatch selects FOUR instantiations from TWO flags (verbatim): 'auto kernel = comb ? (gated ? dsv4_hc_post_f32<true,  true> : dsv4_hc_post_f32<true,  false>)' / '                       : (gated ? dsv4_hc_post_f32<false, true> : dsv4_hc_post_f32<false, false>);'. The chain shape (qwen4exp builds, test-builder verbatim from the Vulkan origin #29520): 'post = ggml_scale(ctx, ggml_sigmoid(ctx, ggml_scale(ctx, post, 1.0f / (float) hc)), 2.0f);' — so gate_in carries 1/hc and gate_out carries 2.0f. Numerics: the fused arm performs the same f32 op sequence (mul → sigmoid → mul) with the same scalars the eager chain applied per-op — bit-identity BY CONSTRUCTION, no tolerance band. DECISION CONTENT: (a) admission is a graph-pattern match on the op chain + edge wiring + zero-bias guard + same-shape guard — a non-null gate node arms the fused path; the ungated instantiation IS the incumbent, byte-identical fallback by construction; (b) the gate is a COMPILE-TIME template flag — `has_comb` × `gated` select four instantiations at dispatch and `if constexpr (gated)` compiles the gate arm to nothing in the fallback posture (zero cost where unfused); (c) gate scalars ride OP PARAMS read host-side at launch, never tensor loads — a SCALE node's factor is launch-known, so the fusion adds zero memory traffic; (d) numerics identical BY CONSTRUCTION — same op order, same scalars; a bias-carrying SCALE or a differently-wired chain REFUSES the fusion (the guard is the correctness envelope, not a fast-path hint). REGIME: a pointwise/unary gate CHAIN with const scalars (SCALE→ACT→SCALE) feeding a consumer that reads each weight element exactly once — the chain output is pure intermediate (written 3×, read 1×), the consumer already indexes the same element position, both scalars host-known at launch. ANTI-REGIME: the chain output has MULTIPLE consumers (the transcendental would recompute per reader, or materialization is forced anyway); the gate scalars are runtime-computed tensors or bias-carrying scales (the guard refuses); the consumer's inner loop re-reads each weight many times (transcendental cost multiplies — precompute-pass territory, see kinship). KINSHIP (do not double-count): moe-router-weight-fold-into-reduce-never-materialize (Batch 220) folds expert-router multiply-weights into a MoE REDUCE — no activation chain, no source rewiring; THIS owns the sigmoid gate-CHAIN fold + the raw-source rewiring (`gate_scale_in->src[0]`) — compose. gate-activation-precompute-pass-token-threshold-gated (Batch 251) owns WHICH pass computes a gate activation (precompute vs in-kernel) at token thresholds; THIS elides materializing the gated weights entirely — a graph-level fusion, orthogonal to where the activation runs. fuse-gate-up-gemv-activation (Batch 251 rider family) fuses gate|up GEMV with activation — related single-kernel fusion shape, distinct stored quantity. NOVEL (grep 'hc.?post|hc.?combine|gate.{0,15}chain|sigmoid.{0,20}fold' over both corpora at claim: ZERO owners of the chain-fold + raw-source rewiring). NotBenchable here (the face is the host graph-pattern match + constexpr dispatch over a graph fusion — the gain is the eliminated intermediate tensor round-trip, 3 writes + 1 read → 1 read at graph scale, which a Rust microbench of a sigmoid+multiply cannot measure; league-relevant as a graph-fusion admission pattern, not an instruction sequence). Source: ggml-org/llama.cpp @ ff5a2337, Apache-2.0 — ggml/src/ggml-cuda/dsv4-hc.cu:149, :185-195, :285-300 + ggml-cuda.cu:3550-3570 + dsv4-hc.cuh:3-6 (origin: the Vulkan HC_POST_GATE fusion #29520 @ 03a667aa). Batch 252 / Plan 256 / Research 287.".to_string(),
            ref_shape: "// naive: hc_post gate weights are MATERIALIZED by a 3-op elementwise chain\n// (SCALE -> SIGMOID -> SCALE, one kernel each), then the consumer kernel\n// reads the materialized tensor. Four kernels; the weights buffer\n// round-trips memory 3 writes + 1 read.\n\n#[inline]\nfn sigmoid(x: f32) -> f32 { 1.0 / (1.0 + (-x).exp()) }\n\nfn scale(src: &[f32], dst: &mut [f32], s: f32) {\n    for i in 0..src.len() { dst[i] = src[i] * s; }\n}\nfn sigmoid_in_place(w: &mut [f32]) {\n    for i in 0..w.len() { w[i] = sigmoid(w[i]); }\n}\n// kernel 4: consumer reads the MATERIALIZED weights + raw x\nfn hc_post(x: &[f32], w: &[f32], out: &mut [f32]) {\n    for (o, (xv, wv)) in out.iter_mut().zip(x.iter().zip(w)) { *o = xv * wv; }\n}\n\nfn naive_chain(x: &[f32], inject: &[f32], out: &mut [f32]) {\n    let (mut a, mut w) = (vec![0.0f32; inject.len()], vec![0.0f32; inject.len()]);\n    scale(inject, &mut a, 1.0 / 32.0); // launch 1 (gate_in op param 1/hc): write 1\n    sigmoid_in_place(&mut a);          // launch 2: write 2\n    scale(&a, &mut w, 2.0);            // launch 3 (gate_out op param *2): read 1 + write 3\n    hc_post(x, &w, out);               // launch 4: the weights' FINAL read\n}\n\n#[test]\nfn naive_materialization_matches_the_chain_math() {\n    let x = [1.0f32, 1.0];\n    let inject = [0.5f32, 4.0];\n    let mut out = [0.0f32; 2];\n    naive_chain(&x, &inject, &mut out);\n    // the chain's own math (gate_in 1/32, gate_out 2), computed directly:\n    assert_eq!(out[0], x[0] * (2.0 * sigmoid(0.5 * (1.0 / 32.0))));\n    assert_eq!(out[1], x[1] * (2.0 * sigmoid(4.0 * (1.0 / 32.0))));\n}\n".to_string(),
            opt_pattern: "// optimized: the CONSUMER takes a `gated` const-generic flag and computes the\n// chain in-register from the RAW weights; the gate scalars ride op params\n// (host-known at launch, never tensor loads) and the host rewires the source\n// to the raw weights via the gate node's src[0]. Four instantiations from\n// two flags; `if GATED` compiles away entirely in the fallback posture.\n\n#[derive(Clone, Copy)]\nstruct GateParams { scale_in: f32, scale_out: f32 } // op params, NOT tensors\n\n#[inline(always)]\nfn sigmoid(x: f32) -> f32 { 1.0 / (1.0 + (-x).exp()) }\n\n// ONE kernel; POST is whatever source the HOST selected (raw inject when gated).\nfn dsv4_hc_post<const GATED: bool>(\n    x: &[f32], post: &[f32], g: GateParams, out: &mut [f32],\n) {\n    for i in 0..out.len() {\n        let mut p = post[i];\n        if GATED {\n            p = g.scale_out * (1.0 / (1.0 + (-(g.scale_in * p)).exp()));\n        }\n        out[i] = x[i] * p;\n    }\n}\n\n// host dispatch shape (the C++ is the same ternary chain over has_comb x gated)\nfn dispatch(has_comb: bool, gated: bool) -> &'static str {\n    match (has_comb, gated) {\n        (true, true) => \"dsv4_hc_post_f32<true, true>\",\n        (true, false) => \"dsv4_hc_post_f32<true, false>\",\n        (false, true) => \"dsv4_hc_post_f32<false, true>\",\n        (false, false) => \"dsv4_hc_post_f32<false, false>\",\n    }\n}\n\n#[test]\nfn fused_arm_bitwise_equals_eager_chain() {\n    // Bit-identity is BY CONSTRUCTION: both paths run the same f32 op\n    // sequence (mul -> sigmoid -> mul) with the same scalars. Inputs chosen\n    // exact-representable so no platform-libm drift can enter (the source's\n    // own shape: gate_in 1/hc, gate_out 2 — powers of two here).\n    const INV_HC: f32 = 1.0 / 32.0; // 2^-5: exact\n    const GATE_OUT: f32 = 2.0;      // exact\n    let g = GateParams { scale_in: INV_HC, scale_out: GATE_OUT };\n    let post_raw = [0.25f32, 2.0, 32.0, -8.0, 0.03125];\n    for &p in &post_raw {\n        // eager chain = the 3 materialized kernels' math, in launch order\n        let a = p * INV_HC;                // SCALE 1 (gate_in param)\n        let b = sigmoid(a);                // SIGMOID\n        let eager = GATE_OUT * b;          // SCALE 2 (gate_out param)\n        let mut out = [0.0f32; 1];\n        dsv4_hc_post::<true>(&[1.0], &[p], g, &mut out);\n        assert_eq!(out[0].to_bits(), eager.to_bits(), \"p = {p}\");\n    }\n    // ungated instantiation: the gate arm compiles away; post IS dst->src[2],\n    // passthrough — the fallback posture must stay byte-identical.\n    let mut out = [0.0f32; 1];\n    dsv4_hc_post::<false>(&[3.0], &[0.5], g, &mut out);\n    assert_eq!(out[0].to_bits(), 1.5f32.to_bits());\n    assert_eq!(dispatch(true, true), \"dsv4_hc_post_f32<true, true>\");\n}\n".to_string(),
        },
        // ── F: the oob-free fast loop's bound is the CONTRACT that makes
        // the elided check sound — it must INCLUDE the last fully-covered
        // tile, or one full tile per row-block silently pays the check. ──
        KernelRule {
            rule_id: "oob-free-loop-inclusive-of-last-full-tile".to_string(),
            gpu_concept: "MECHANISM (oob-free fast loop inclusive of its last full tile; category F — flash-attention tiling): the checked/unchecked KV split in flash_attn_tile bounded its fast arm with 'while (k_VKQ_0 < k_VKQ_max - nbatch_fa)'; PR #30572 repairs it to 'while (k_VKQ_0 <= k_VKQ_max - nbatch_fa)' — body 'constexpr bool oob_check = false;' (compile-time elided bounds checks) — fattn-tile.cuh:958-959, ggml-org/llama.cpp @ 5aeac37a. The one-character '<' → '<=' moves the LAST FULLY-COVERED tile — the one starting exactly at k_VKQ_max - nbatch_fa, spanning [k_VKQ_max - nbatch_fa, k_VKQ_max) — from the checked path into the unchecked path: a tile whose whole [k_VKQ_0, k_VKQ_0 + nbatch_fa) range lies inside the KV bound needs no OOB check, so the strict bound wasted the check on every iteration of that tile. The commit subject states the face verbatim: 'ggml-cuda: fattn do not check oob if k_VKQ_max = (k_VKQ_max - nbatch_fa)' — when the remaining span EXACTLY equals the batch step, the tile is fully covered and belongs on the fast path. DECISION CONTENT: (a) the oob-free loop's bound is INCLUSIVE of the last fully-covered tile — 'k0 <= max - step' is the CONTRACT that makes the elided check sound: the loop may only take tiles whose [k0, k0 + step) span is fully covered by the KV bound; (b) the partial tile (k_max % step != 0) ALWAYS falls to the checked branch — never fold it into the fast loop, never let the inclusive bound reach it (signed math: a negative bound admits nothing, so sub-step spans go wholly to the checked arm); (c) one-character bounds drift is a silent perf tax invisible to correctness tests — both bounds compute the identical answer, only the fast/checked partition moves; pin the bound with a tile-coverage partition test (fast tiles + ≤1 checked tile == exact cover of the span, fast-tile count differing by exactly one on the step-aligned face), never a numerics test; (d) the law transfers to ANY checked/unchecked split-loop over stepped ranges (SIMD tails, chunked copies, batched reduction scans): the unchecked arm's bound is inclusive of the last step-aligned fully-covered chunk. REGIME: stepped KV/batch loops with a fixed batch step (nbatch_fa) and a constexpr-elided OOB-free fast arm beside a checked arm; step-aligned spans (k_VKQ_max a whole number of batch steps) are common, so the strict bound demoted a full tile of every row-block. ANTI-REGIME: single-tile loops with no step; bounds where max - step underflows below zero (the fast arm takes nothing and the checked arm owns everything); checked arms whose per-iteration guard is free (nothing to elide); tails that need clamped views for correctness — those stay on the checked path, the inclusive bound never reaches them. KINSHIP (do not double-count): dense-fast-path-bounded-by-selector-coverage (Batch 26) owns the fast path's ADMISSION bound (whether the regime enters the fast path at all); THIS owns the loop bound WITHIN an admitted regime (which tiles the unchecked loop may take). pad-tail-to-fixed-tile pads the tail INTO the fixed-tile regime; THIS bounds the fast loop to the provably-covered span instead of padding (compose: padding can make every tile fully covered, at which point this rule's bound is the whole loop). extent-clamped-operand-views-partial-k-tile (entries_gpu_34) clamps VIEWS for the partial tail tile (correctness of the checked path); THIS routes fully-covered tiles AWAY from that path. tail-simdgroup-cull-barriers-preserved is tail culling with barriers preserved — a different axis. NOVEL (grep 'oob.?check|k_VKQ_max|fully.covered.{0,20}tile|inclusive.{0,20}bound' over both corpora at claim: ZERO owners of the loop-bound law). NotBenchable here (the tax is one tile per row-block — source-stated shape, not a microbench win measurable on this box; the oracle is CPU-testable: tile-coverage partition (fast tiles + ≤1 checked tile) == exact cover of the KV span for BOTH bounds, with the fast-tile COUNT differing by exactly one on the step-aligned face). Source: ggml-org/llama.cpp @ 5aeac37a, Apache-2.0 — ggml/src/ggml-cuda/fattn-tile.cuh:958-959. Batch 252 / Plan 256 / Research 287.".to_string(),
            ref_shape: "// ref_shape: the fast (oob-free) arm EXCLUDES its last fully-covered\n// tile -- the strict '<' bound demotes one full tile per row-block to\n// the checked arm. The answer is identical either way; only the\n// fast/checked partition moves (a silent perf tax).\n#![allow(dead_code)]\n\nconst STEP: usize = 64; // nbatch_fa -- the fixed fast-path batch step\n\n#[inline(always)]\nfn process_tile<const OOB_CHECK: bool>(k0: usize, k_max: usize, s: &mut [f32], q: &[f32], k: &[f32]) {\n    for i in 0..STEP {\n        // OOB_CHECK is a compile-time const: false elides this guard entirely.\n        if OOB_CHECK && k0 + i >= k_max {\n            break;\n        }\n        // scores[k0 + i] += dot(q[..], k[k0 + i][..]) -- body elided\n        let _ = (&*s, q, k);\n    }\n}\n\nfn fattn_tile_kv_loop(k_max: usize, s: &mut [f32], q: &[f32], k: &[f32]) {\n    let mut k0: usize = 0;\n    // fast arm: constexpr oob_check = false -- bounds checks compiled out\n    while (k0 as isize) < k_max as isize - STEP as isize {\n        // STRICT < -- the defect: the tile starting at k_max - STEP is\n        // fully covered by the KV bound yet pays the checked path\n        process_tile::<false>(k0, k_max, s, q, k);\n        k0 += STEP;\n    }\n    // checked arm: EVERYTHING left -- the true partial tail AND the\n    // last FULL tile when k_max % STEP == 0\n    while (k0 as isize) < k_max as isize {\n        process_tile::<true>(k0, k_max, s, q, k);\n        k0 += STEP;\n    }\n}\n".to_string(),
            opt_pattern: "// opt_pattern: ONE character -- '<' becomes '<='. The fast arm now\n// ADMITS the tile starting exactly at k_max - STEP: its [k0, k0 + STEP)\n// span lies fully inside the KV bound, the OOB check is provably dead\n// there, and only the true partial tail (k_max % STEP != 0) stays on\n// the checked path. process_tile is the ref_shape helper, unchanged;\n// the law is the PARTITION of the span, so the test pins coverage,\n// never numerics.\n#![allow(dead_code)]\n\nconst STEP: usize = 64; // nbatch_fa -- the fixed fast-path batch step\n\n#[inline(always)]\nfn process_tile<const OOB_CHECK: bool>(k0: usize, k_max: usize, s: &mut [f32], q: &[f32], k: &[f32]) {\n    for i in 0..STEP {\n        // OOB_CHECK is a compile-time const: false elides this guard entirely.\n        if OOB_CHECK && k0 + i >= k_max {\n            break;\n        }\n        // scores[k0 + i] += dot(q[..], k[k0 + i][..]) -- body elided\n        let _ = (&*s, q, k);\n    }\n}\n\nfn fattn_tile_kv_loop(k_max: usize, s: &mut [f32], q: &[f32], k: &[f32]) {\n    let mut k0: usize = 0;\n    // fast arm: constexpr oob_check = false -- the INCLUSIVE bound is\n    // the contract that licenses the elided check: only tiles whose\n    // whole [k0, k0 + STEP) span is covered may enter\n    while (k0 as isize) <= k_max as isize - STEP as isize {\n        process_tile::<false>(k0, k_max, s, q, k);\n        k0 += STEP;\n    }\n    while (k0 as isize) < k_max as isize {\n        process_tile::<true>(k0, k_max, s, q, k);\n        k0 += STEP;\n    }\n}\n\n#[test]\nfn inclusive_bound_covers_and_promotes_the_last_full_tile() {\n    const STEP: usize = 64;\n\n    fn partition(k_max: usize, inclusive: bool) -> (Vec<(usize, usize)>, Vec<(usize, usize)>) {\n        let mut fast = Vec::new();\n        let mut checked = Vec::new();\n        let bound = k_max as isize - STEP as isize; // signed math, mirrors the CUDA original\n        let mut k0: isize = 0;\n        while if inclusive { k0 <= bound } else { k0 < bound } {\n            fast.push((k0 as usize, k0 as usize + STEP));\n            k0 += STEP as isize;\n        }\n        while k0 < k_max as isize {\n            checked.push((k0 as usize, (k0 + STEP as isize).min(k_max as isize) as usize));\n            k0 += STEP as isize;\n        }\n        (fast, checked)\n    }\n\n    for &k_max in &[0usize, 1, STEP - 1, STEP, STEP + 1, 3 * STEP, 5 * STEP + 17] {\n        let (n_fast, n_checked) = partition(k_max, false); // naive strict bound\n        let (o_fast, o_checked) = partition(k_max, true); // optimized inclusive bound\n        // BOTH partitions exactly cover 0..k_max with no overlap\n        for &(fast, checked) in &[(&n_fast, &n_checked), (&o_fast, &o_checked)] {\n            let mut cover: Vec<usize> =\n                fast.iter().chain(checked.iter()).flat_map(|&(a, b)| a..b).collect();\n            cover.sort_unstable();\n            assert!(!cover.windows(2).any(|w| w[0] == w[1]), \"no overlap\");\n            assert_eq!(cover.len(), k_max, \"exact cover of the KV span\");\n        }\n        // every fast tile is fully covered by construction\n        for &(a, b) in &o_fast {\n            assert_eq!(b - a, STEP);\n            assert!(b <= k_max);\n        }\n        // optimized fast count >= naive; strictly +1 on the exact-\n        // equality face the commit names (the tile at k_max - nbatch_fa)\n        assert!(o_fast.len() >= n_fast.len());\n        if k_max % STEP == 0 && k_max >= STEP {\n            assert_eq!(o_fast.len(), n_fast.len() + 1);\n            assert!(o_checked.is_empty(), \"step-aligned span never touches the checked arm\");\n        }\n        // the partial tail ALWAYS falls to the checked branch\n        if k_max % STEP != 0 && k_max > 0 {\n            assert_eq!(o_checked.len(), 1);\n        }\n    }\n    // and the shipped loop itself exercises the inclusive bound: a\n    // step-aligned span ends exactly at the fast/checked seam\n    {\n        let mut s = vec![0.0f32; 64];\n        let q = vec![0.0f32; 8];\n        let k = vec![0.0f32; 64 * 8];\n        fattn_tile_kv_loop(3 * STEP, &mut s, &q, &k); // no panic: the fast arm took all three tiles\n        fattn_tile_kv_loop(3 * STEP + 17, &mut s, &q, &k); // the tail goes to the checked arm\n    }\n}\n".to_string(),
        },
    ]
}
